function resetCampaignEncounter(index,region=0){normalizeWorld();const [name,key,list]=campaignRegions()[region];if(region===0&&s.character.rank!=='F')return say('Promoted campaign records cannot be reset.');if(index<0||index>=s.world[key])return;const affected=s.completed.filter(q=>q.campaignVersion===2&&(q.campaignRegion>region||(q.campaignRegion===region&&q.campaignIndex>=index)));const xp=affected.reduce((a,q)=>a+(q.xpAwarded||0),0),gold=affected.reduce((a,q)=>a+(q.goldAwarded||0),0);gameConfirm({title:"Campaign Records",message:'Reset this and later campaign encounters, reversing their XP and Gold?',accept:"Reset Encounters",onConfirm:()=>{if(index>=s.world[key])return;const total=Math.max(0,s.character.level*100+s.character.xp-xp);s.character.level=Math.floor(total/100);s.character.xp=total%100;s.character.gold=Math.max(0,s.character.gold-gold);for(const key of ['strength','dexterity','intelligence'])s.character[key+'Xp']=Math.max(0,(s.character[key+'Xp']||0)-affected.filter(q=>(q.attributeKey||'strength')===key).reduce((a,q)=>a+(q.attributeXp||0),0));s.character.constitutionXp=Math.max(0,(s.character.constitutionXp||0)-affected.reduce((a,q)=>a+(q.conXp||0),0));affected.forEach(q=>{removeLoot(q.loot);(q.loots||[]).forEach(removeLoot)});s.completed=s.completed.filter(q=>!affected.includes(q));s.world[key]=index;if(region===0)s.world.burrowCleared=0;localStorage.removeItem(UNDO_KEY);lastQuestUndo=null;save();render();}})}
