function monsterLoot(name,threat){const drops=baseMonsterLoot(name,threat);if(/wolf|fenrir/i.test(name)){if(Math.random()<.4)drops.push(addLoot('Bone','Common'));if(Math.random()<.35)drops.push(addLoot('Wolf Claw','Common'))}return drops}function baseMonsterLoot(name,threat){let table;if(name==='Slime King')table=['Giant Slime Jelly','Giant Slime Essence','Giant Slime Core','Mystic Water'];else if(name==='Alpha Wolf')table=['Alpha Fur','Alpha Pelt','Alpha Fang','Alpha Core'];else if(name==='Fenrir')table=['Fenrir Fur','Fenrir Pelt',"Fenrir's Fang",'Fenrir Frost Core'];else if(/slime/i.test(name))table=[name.replace(/ Slime/i,'')+' Jelly','Slime Essence','Magic Stone','Mystic Water'];else if(/wolf/i.test(name))table=['Fur','Raw Meat','Wolf Pelt','Wolf Fang'];if(!table)return [];const rarities=['Common','Uncommon','Rare','Epic'],n=phaseCount({name,threat});if(n===1){const r=rarityRoll();return [addLoot(table[rarities.indexOf(r)],r)]}const items=rarities.slice(0,n).map((r,i)=>addLoot(table[i],r));if(rarityRoll()==='Epic')items.push(addLoot(table[3],'Epic'));return items}
