if(tab==='record'){v=`<section class="panel"><h2>Testing Controls</h2><p class="muted">Undo the latest mob victory or quest completion, including its rewards and progression.</p><button class="btn ghost" onclick="resetLastQuestAction()" ${lastQuestUndo?'':'disabled'}>↶ Reset Last Quest Action</button></section><section class="panel"><h2>Completed Quest Record</h2><p class="muted">The Guild's permanent record of reported victories.</p>${s.completed.length?[...s.completed].reverse().map(q=>card(q,true)).join(''):'<p class="muted">No completed quests yet.</p>'}</section>`}
if(tab==='shop'){let goods=[['v5','Small Reward Voucher','A small treat or new game fund.',5],['v10','Comfort Voucher','A cheat meal or equivalent indulgence.',10],['v20','Fun Reward Voucher','Put Gold toward something enjoyable.',20],['v50','Grand Reward Voucher','A planned cheat day or special outing.',50],['v100','Adventurer’s Day Voucher','A day dedicated to yourself.',100],['sword','Training Sword · Future Unlock','Placeholder; training rules not yet implemented.',60,true],['bow','Field Bow · Future Unlock','Placeholder; training rules not yet implemented.',80,true]];v=`<section class="panel"><h2>Guild Reward Shop</h2><button class="btn ghost" onclick="go('guild')">← Guild</button><div class="between"><span class="small">AVAILABLE TREASURY</span><b class="price">${gold(s.character.gold)}</b></div><p class="muted">Gold is earned through completed quests. Voucher purchases are tracked; redemption is handled outside this alpha.</p>${goods.map(g=>`<div class="item"><div><b>${g[1]}</b><p>${g[2]}</p><b class="price">${gold(g[3])}</b></div><button class="btn ${g[4]?'ghost':'gold'}" ${g[4]||s.character.gold<g[3]?'disabled':''} onclick="buy('${g[0]}','${g[1]}',${g[3]})">${g[4]?'LOCKED':'BUY'}</button></div>`).join('')}<div class="notice">Class Change unlocks after every reward voucher tier has been purchased at least once. Class changes are not implemented in this alpha.</div></section><section class="panel"><h2>Inventory</h2>${s.inventory.length?s.inventory.map(i=>`<div class="item"><b style="color:${rarityColor(i.rarity)}">${esc(i.name)}</b><span class="tag">${i.rarity?i.rarity+' ×'+(i.quantity||1):'OWNED'}</span></div>`).join(''):'<p class="muted">Your inventory is empty.</p>'}</section>`}
