function inventoryEntries(){return s.inventory.filter(i=>inventoryCategory(i)!=='Patterns')}let inventoryTab='Weapons';function inventoryCategory(i){if(i.id?.startsWith('pattern-')||/^Pattern:/i.test(i.name||''))return 'Patterns';const g=gearInfo(i);if(g)return g.slot==='weapon'?'Weapons':'Armor';if(i.chestKind)return 'Consumables';if(i.category==='consumable'||i.type==='consumable'||/potion|elixir|voucher/i.test(i.name||''))return 'Consumables';if(i.category==='junk'||i.type==='junk')return 'Junk';if(i.category==='material'||i.type==='material'||i.id?.startsWith('loot:')||i.id?.startsWith('gather:')||/pattern:|ore|flower|wood log|bird nest/i.test(i.name||''))return 'Materials';return 'Junk'}function setInventoryTab(t){if(!['Weapons','Armor','Materials','Consumables','Junk'].includes(t))return;inventoryTab=t;render()}function inventoryTabs(){return '<div class="inventory-tabs">'+['Weapons','Armor','Materials','Consumables','Junk'].map(t=>'<button class="btn '+(inventoryTab===t?'gold':'ghost')+'" aria-pressed="'+(inventoryTab===t)+'" onclick="setInventoryTab(\''+t+'\')">'+t+'<small>'+inventoryEntries().filter(i=>inventoryCategory(i)===t).length+'</small></button>').join('')+'</div>'}
function setCharacterSection(key){characterSection=key;render();window.scrollTo(0,0)}
/* portraits loaded separately */
function profilePanel(){return `<section class="panel"><div class="between"><h2>Edit Adventurer Profile</h2><button class="btn ghost" onclick="setCharacterSection('status')">Done</button></div><div class="portrait-grid">${presetPortraits.map((p,i)=>`<button type="button" class="portrait-choice" onclick="choosePortrait(${i})"><img src="${p.src}" alt="${esc(p.label)}" title="${esc(p.label)}"></button>`).join('')}</div><label class="small" for="adventurerName">NAME</label><input id="adventurerName" maxlength="32" value="${esc(s.character.name)}"><div class="actions"><button class="btn gold" onclick="saveProfileName()">Save name</button><button class="btn ghost" onclick="document.querySelector('#avatarFile').click()">Upload picture</button><button class="btn ghost" onclick="removeAvatar()" ${s.character.avatar?'':'disabled'}>Remove picture</button></div><input id="avatarFile" type="file" accept="image/*" hidden onchange="uploadAvatar(event)"><div class="crop-controls"><label>Zoom <input type="range" min="1" max="2.5" step="0.05" value="${s.character.avatarZoom}" oninput="updateAvatarFrame('avatarZoom',this.value)" onchange="saveAvatarFrame()"></label><label>Horizontal framing <input type="range" min="0" max="100" value="${s.character.avatarX}" oninput="updateAvatarFrame('avatarX',this.value)" onchange="saveAvatarFrame()"></label><label>Vertical framing <input type="range" min="0" max="100" value="${s.character.avatarY}" oninput="updateAvatarFrame('avatarY',this.value)" onchange="saveAvatarFrame()"></label><button class="btn ghost" onclick="resetAvatarFrame()">Reset framing</button></div></section>`}
function editCharacterProfile(){characterSection='profile';render();document.querySelector('#adventurerName')?.scrollIntoView({block:'center'});}
function choosePortrait(i){if(!presetPortraits[i])return;s.character.avatar=presetPortraits[i].src;s.character.avatarZoom=1;s.character.avatarX=50;s.character.avatarY=50;save();render();say('Portrait saved.');}
function saveProfileName(){const input=document.querySelector('#adventurerName');if(!input)return;const name=input.value.trim();if(!name)return say('Enter a name for your Adventurer.');s.character.name=name.slice(0,32);save();render();say('Adventurer name saved.')}
function uploadAvatar(event){const file=event.target.files&&event.target.files[0];if(!file)return;if(!file.type.startsWith('image/')){say('Please choose an image file.');event.target.value='';return}if(file.size>8*1024*1024){say('That image is too large. Choose one under 8 MB.');event.target.value='';return}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const max=512,scale=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);s.character.avatar=canvas.toDataURL('image/jpeg',0.82);s.character.avatarZoom=1;s.character.avatarX=50;s.character.avatarY=50;save();render();say('Profile picture saved. Adjust the framing below.');};img.onerror=()=>say('Could not read that image. Try another picture.');img.src=reader.result;};reader.onerror=()=>say('Could not load that image.');reader.readAsDataURL(file);event.target.value=''}

function updateAvatarFrame(key,value){s.character[key]=Number(value);document.querySelectorAll('.crest img,.profile-preview,.status-portrait img').forEach(img=>{img.style.setProperty('--avatar-zoom',s.character.avatarZoom);img.style.setProperty('--avatar-x',s.character.avatarX+'%');img.style.setProperty('--avatar-y',s.character.avatarY+'%');if(img.closest('.crest'))img.style.setProperty('--avatar-crest-y',Math.min(100,s.character.avatarY+20)+'%')})}
function saveAvatarFrame(){save();say('Portrait framing saved.')}
function resetAvatarFrame(){s.character.avatarZoom=1;s.character.avatarX=50;s.character.avatarY=50;save();render();say('Portrait framing reset.')}
function removeAvatar(){if(!s.character.avatar)return;s.character.avatar='';save();render();say('Profile picture removed.')}
function go(t){if(s.dungeonRoom!=null&&t!=='combat'&&t!=='dungeon')return say('The dungeon must be completed first.');if(battle&&t!=='combat')return say('Finish or retreat from combat first.');tab=t;if(t==='status')characterSection='status';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));render()}document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>go(b.dataset.tab));
function awardCharacterXp(xp){const old=s.character.level;s.character.xp+=xp;const levels=Math.floor(s.character.xp/100);s.character.xp-=levels*100;const chests=[];for(let j=1;j<=levels;j++){const level=old+j;s.character.level=level;if(level<=(s.character.highestRewardedLevel??old))continue;const rarity=level%25===0?'Epic':level%10===0?'Rare':level%5===0?'Uncommon':'Common';const chest={id:'level-chest-'+level+'-'+Date.now(),name:chestTierName(rarity)+' Chest',chestKind:'Tier',category:'consumable',rarity,levelReward:level};s.inventory.push(chest);chests.push(chest);s.character.highestRewardedLevel=level}return chests}function levelConfetti(d){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const layer=document.createElement('div');layer.className='level-confetti';layer.setAttribute('aria-hidden','true');const colors=['#e7bf65','#fff0b0','#c78c35','#79b7e8','#b39ae8','#76c9a1','#e58a85'];for(let i=0;i<64;i++){const p=document.createElement('i');p.style.cssText='left:'+(Math.random()*100)+'%;background:'+colors[i%colors.length]+';--drift:'+((Math.random()-.5)*160)+'px;--spin:'+(360+Math.random()*720)+'deg;animation-delay:'+Math.random()*.65+'s;animation-duration:'+(1.7+Math.random()*.9)+'s;width:'+(5+Math.random()*5)+'px;height:'+(7+Math.random()*7)+'px';layer.appendChild(p)}d.appendChild(layer);setTimeout(()=>layer.remove(),3400)}function showLevelRewards(chests){if(!chests.length)return;const d=document.createElement('dialog');d.id='levelRewardDialog';d.className='treasure-dialog';d.innerHTML='<div class="victory-heading"><h2 style="color:#e7bf65">✦ LEVEL UP! ✦</h2><p>Level '+s.character.level+' reached!</p></div>'+chests.map(i=>'<div class="treasure-stage opening">'+chestSprite(i)+'<div class="treasure-flash"></div></div><p style="color:'+rarityColor(i.rarity)+'">Level '+i.levelReward+' · '+esc(i.name)+' added to inventory</p>').join('')+'<button class="btn gold" style="width:100%">Continue</button>';d.querySelector('button').onclick=()=>d.close();d.addEventListener('close',()=>d.remove());document.body.appendChild(d);d.showModal();levelConfetti(d)}function awardQuest(q,xpOverride=null){s.character.gold+=q.reward;const xp=xpOverride??q.xpReward??q.reward;const chests=awardCharacterXp(xp);if(chests.length)setTimeout(()=>showLevelRewards(chests),0);return xp}
function complete(id){let i=s.active.findIndex(q=>q.id===id);if(i<0)return;let q=s.active[i];if(q.questMode==='combat')return say('Combat quests must be completed in the Combat Arena.');gameConfirm({title:"Guild Receptionist",message:`Report "${q.title}" complete and award ${q.reward} Gold and ${formatXp(q.xpReward??q.reward)} XP?`,accept:"Report Complete",onConfirm:()=>{i=s.active.indexOf(q);if(i<0)return;markQuestUndo();s.active.splice(i,1);let xp=awardQuest(q);s.completed.push({...q,date:new Date().toLocaleDateString()});save();render();say(`Quest complete! +${q.reward} Gold · +${formatXp(xp)} XP.`)}})}
function addQuest(){let title=document.querySelector('#qt').value.trim(),desc=document.querySelector('#qd').value.trim(),mode=document.querySelector('#qmode').value;if(!title||!desc)return say('Enter a title and objective.');s.active.push({id:String(s.next++).padStart(3,'0'),title,type:mode==='combat'?'COMBAT ASSIGNMENT':mode==='daily'?'DAILY QUEST':'FIELD QUEST',questMode:mode,description:desc,help:desc,reward:10,xpReward:10});save();render();say('Quest added.')}
function dexValue(value){return Math.max(0,Math.floor(Number(value)||0))}
const attributeHelp={strength:'Sword and unarmed damage: +1 per rep every 2 Strength.',constitution:'Maximum health: +5 HP per Constitution point above 1.',dexterity:'Combat initiative, dodge chance and bow damage: +1 per rep every 2 Dexterity.',intelligence:'Staff damage: +1 per rep every 2 Intelligence.'};function attributeLevel(key){return 4+(Number(s.character[key])||1)+Math.floor((s.character[key+'Xp']||0)/100)+gearBonus(key)}function playerDex(){return dexValue(attributeLevel('dexterity'))}
function rollEnemyDamage(base,heavy=false){const critical=Math.random()<.1;const amount=critical?base+2:Math.max(1,base-2+Math.floor(Math.random()*4));return amount*(heavy?2:1)}
function enemyDex(name){return /fenrir/i.test(name)?20:/wolf/i.test(name)?12:/slime/i.test(name)?2:1}
function dodgeChance(dex){return Math.min(1,Math.floor(dexValue(dex)/10)*0.1)}
function playerDodge(){return Math.random()<Math.min(1,dodgeChance(battle.playerDex)+['weapon','helm','chest','pants','gloves','boots'].reduce((n,slot)=>n+(equippedGear(slot)?.evasion||0),0))}function rollDodge(dex){return Math.random()<dodgeChance(dex)}
function slimeAttackVisual(name,move,outcome,unit=null){const label=move?.[0]||'';let kind=name==='Green Slime'?(label==='Jump'?'jump':label==='Slime Spit'?'spit':''):name==='Slime King'?(label==='Triple Spit'?'purple':/Slam|Bounce/.test(label)?'jump':''):/wolf|fenrir/i.test(name)?(/howl/i.test(label)?'howl':/bite|snap|maul/i.test(label)?'bite':/rend|ravage|wrath/i.test(label)?'rend':/charge|pounce|lunge|ambush/i.test(label)?'charge':''):'';if(!kind)return;const b=battle;(b.slimeEffects??=[]).push({kind,outcome,slot:unit?b.group.indexOf(unit):0})}
function tripleSpit(unit=null,block=0){let damage=0,blocked=0,dodges=0;for(let i=0;i<3;i++){const dodge=playerDodge(),used=dodge?0:Math.min(block,2),hit=dodge?0:2-used;block-=used;blocked+=used;damage+=hit;dodges+=Number(dodge);slimeAttackVisual('Slime King',['Triple Spit'],dodge?'dodge':hit?'hit':'block',unit)}battle.playerHp=Math.max(0,battle.playerHp-damage);return {damage,blocked,dodges}}
function wolfEffect(fx,sprite,scene){const layer=document.createElement('div');layer.className='wolf-fx '+fx.kind+' '+fx.outcome;layer.setAttribute('aria-hidden','true');if(fx.kind==='howl'){layer.innerHTML='<i></i><i></i><i></i>';scene.animate([{transform:'translateX(0)'},{transform:'translateX(-3px)'},{transform:'translateX(3px)'},{transform:'translateX(0)'}],{duration:160,iterations:3})}else if(fx.outcome==='block'){layer.innerHTML='<span class="wolf-block">🛡</span><b>✦</b>'}else if(fx.kind==='bite'){layer.style.setProperty('--bite-angle',([-45,-30,-15,0,15,30,45][Math.floor(Math.random()*7)])+'deg');layer.innerHTML='<svg viewBox="0 0 300 220"><g class="jaw-top"><path d="M15 20Q150 -15 285 20L265 75 245 40 220 92 195 45 170 95 150 48 125 95 100 45 75 92 50 40 30 75Z"/></g><g class="jaw-bottom"><path d="M15 200Q150 235 285 200L265 145 245 180 220 128 195 175 170 125 150 172 125 125 100 175 75 128 50 180 30 145Z"/></g></svg>';if(fx.outcome==='hit'){layer.insertAdjacentHTML('beforeend','<span class="bite-impact"></span>');setTimeout(()=>scene.animate([{transform:'translateX(0)'},{transform:'translateX(-4px)'},{transform:'translateX(4px)'},{transform:'translateX(0)'}],{duration:120,iterations:2}),230)}}else if(fx.kind==='rend'){layer.innerHTML='<svg viewBox="0 0 320 340">'+[0,65,130].map((x,i)=>'<g transform="translate('+x+' 0)"><path class="rend-deep" style="animation-delay:'+i*85+'ms" d="M12 315Q65 160 174 20Q111 185 12 315Z"/><path class="rend-bright" style="animation-delay:'+i*85+'ms" d="M12 315Q77 156 174 20Q104 190 12 315Z"/></g>').join('')+'</svg>';if(fx.outcome==='hit')scene.animate([{transform:'translateX(0)'},{transform:'translateX(-5px)'},{transform:'translateX(5px)'},{transform:'translateX(0)'}],{duration:130,iterations:3})}else{layer.innerHTML='<span class="charge-flash"></span>';if(sprite)sprite.animate([{transform:'scale(1)'},{transform:'scale(1.35) translateY(12%)'},{transform:'scale(1)'}],{duration:350});if(fx.outcome==='hit')scene.animate([{transform:'translateX(0)'},{transform:'translateX(-5px)'},{transform:'translateX(5px)'},{transform:'translateX(0)'}],{duration:120,iterations:3})}document.body.appendChild(layer);setTimeout(()=>layer.remove(),2400)}
function playSlimeEffects(){if(!battle?.slimeEffects?.length)return;const effects=battle.slimeEffects.splice(0);if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const b=battle;effects.forEach((fx,i)=>setTimeout(()=>{if(battle!==b||tab!=='combat')return;const scene=document.querySelector('.battle-scene');if(!scene)return;const unit=b.group?scene.querySelector('.battle-unit[style="--slot:'+(fx.slot+1)+'"]'):scene;const sprite=unit?.querySelector('.slime-sprite,.wolf-sprite');if(['bite','rend','charge','howl'].includes(fx.kind)){wolfEffect(fx,sprite,scene);return}if(fx.kind==='jump'&&sprite){sprite.animate([{transform:'scale(1)'},{transform:'translateY(-40%) scale(.9,1.15)'},{transform:'translateY(8%) scale(1.32,.76)'},{transform:'scale(1)'}],{duration:550});return}if(!['spit','purple'].includes(fx.kind))return;const layer=document.createElement('div');layer.className='slime-fx '+fx.outcome+' '+fx.kind;layer.setAttribute('aria-hidden','true');const rect=sprite?.getBoundingClientRect();if(rect){layer.style.setProperty('--sx',(rect.left+rect.width/2)+'px');layer.style.setProperty('--sy',(rect.top+rect.height*.65)+'px')}layer.innerHTML='<i class="slime-shot"></i><div class="slime-impact">'+(fx.outcome==='block'?'<span class="slime-shield">🛡</span>':'')+'<svg viewBox="0 0 300 240"><path d="M149 46Q171 8 188 45L202 77Q250 35 258 75Q267 100 233 120Q298 142 265 172Q247 186 204 170Q219 229 185 220Q165 218 153 180Q107 238 82 209Q65 192 94 158Q15 184 19 143Q22 115 75 109Q28 67 63 48Q86 38 116 82Z" fill="#79bd31" stroke="#b4e95b" stroke-width="3"/><ellipse cx="117" cy="103" rx="25" ry="10" fill="#d3f58c" opacity=".6"/><circle cx="36" cy="45" r="9" fill="#91cc43"/><circle cx="267" cy="44" r="12" fill="#91cc43"/><circle cx="246" cy="211" r="8" fill="#91cc43"/></svg></div>';document.body.appendChild(layer);setTimeout(()=>layer.remove(),1600)},i*480))}
function enemyStrike(){const type=battle.attackType||'light';bestiaryObserve(moveLabel(battle.move,type));if(type==='guard'){battle.guarding=true;return battle.enemyName+' uses '+moveLabel(battle.move,type)+', reducing your next attack by half.'}if(type==='heavy'&&!battle.heavyCharged){battle.heavyCharged=true;return battle.enemyName+' charges '+moveLabel(battle.move,type)+'! It will land on the next enemy action.'}if(battle.move?.[0]==='Triple Spit'){const t=tripleSpit();return 'Triple Spit: '+t.damage+' damage, '+t.dodges+' dodged.'}const heavy=type==='heavy'&&battle.heavyCharged;const dmg=rollEnemyDamage(battle.attackDamage,heavy);const dodged=playerDodge();slimeAttackVisual(battle.enemyName,battle.move,dodged?"dodge":"hit");battle.playerHp=Math.max(0,battle.playerHp-(dodged?0:dmg));if(heavy)battle.heavyCharged=false;if(type==='rush'&&!dodged&&battle.playerHp>0&&moveStuns(battle.move))battle.stunned=true;const msg=dodged?'You dodge the '+type+' attack!':battle.enemyName+' uses '+moveLabel(battle.move,type)+' for '+dmg+' damage.';return msg+(battle.stunned?' You are STUNNED and lose your next turn!':'')}
function rollInitiative(){battle.playerDex=playerDex();battle.enemyDex=enemyDex(battle.enemyName);battle.playerFirst=battle.playerDex===battle.enemyDex?Math.random()<0.5:battle.playerDex>battle.enemyDex;battle.log+=battle.playerFirst?' You have initiative and strike first.':' The enemy has initiative and attacks first.'}function prepareInitiative(){battle.openingTurn=true;rollInitiative()}
function pickEnemyAttack(){if(battle.heavyCharged&&battle.move){battle.attackType='heavy';return}battle.move=rollMove(battle.enemyName);battle.attackType=battle.move[1]}
function attackPreview(){if(battle.group)return battle.group.filter(m=>m.hp).map(m=>moveLabel(m.move,m.type)+(m.heavy?' (incoming)':'')).join(' · ');return moveLabel(battle.move,battle.attackType)+' — '+(battle.heavyCharged?'HEAVY ATTACK INCOMING!':moveDescription(battle.move||['',battle.attackType]))}
function naturalCount(n){return n<.4?1:n<.7?2:3}
function encounterRoster(e,list,count,farming,index,region){if(farming)return Array(count).fill(e);const minions={'Slime King':'Green Slime','Alpha Wolf':'Wild Wolf','Fenrir':'Grey Wolf','Goblin Shaman':'Goblin Scout','Goblin King':'Goblin Brute'};const m=list.find(x=>x[0]===minions[e[0]]);if(m)return [m,m,e];const pool=list.slice(0,index).filter(x=>!x[6]&&!Object.hasOwn(minions,x[0]));return [e,...Array.from({length:naturalCount(Math.random())-1},()=>pool.length&&Math.random()<.5?pool[Math.floor(Math.random()*pool.length)]:e)]}
function monsterFamily(name){return /slime/i.test(name)?'slime':/wolf|fenrir/i.test(name)?'wolf':/goblin/i.test(name)?'goblin':name}
function packBonus(m,group){return m.hp?Math.max(0,group.filter(x=>x.hp&&monsterFamily(x.name)===monsterFamily(m.name)).length-1):0}
function beginCampaignEncounter(index,region=0,count=1){if(s.recoveryPending)return showGuildRecovery();normalizeWorld();const [name,key,list]=campaignRegions()[region];if((!regionAllowed(region))||!Number.isInteger(index)||index<0||index>s.world[key]||index>=10)return say('That encounter is locked.');const e=list[index],farming=index<s.world[key];if(e[6]){if(farming)return say('This chest has already been claimed.');markQuestUndo();s.character.gold+=e[6];s.world[key]++;s.completed.push({id:'CAM-'+Date.now(),title:'Treasure Chest · '+name,type:'CAMPAIGN TREASURE',campaignVersion:2,campaignRegion:region,campaignIndex:index,goldAwarded:e[6],xpAwarded:0,date:new Date().toLocaleDateString(),result:'CLAIMED'});save();render();return say('Treasure found! +'+e[6]+' Gold · +10 Rank XP.')}count=farming?Math.max(1,Math.min(5,Math.floor(Number(count)||1))):1;const roster=encounterRoster(e,list,count,farming,index,region);count=roster.length;battle={farming,count,killed:0,campaign:true,campaignRegion:region,returnTab:'world',campaignIndex:index,questId:null,enemyName:e[0],enemyLevel:e[1],enemyMax:e[2],enemyHp:e[2],playerHp:s.character.hp??maxPlayerHp(),attackDamage:e[3],xpReward:e[4],threat:e[5],defendExercise:'crunches',counterExercise:'push-ups',turn:1,totalDamage:0,staggered:false,phase:'choose',mode:null,log:e[0]+' blocks your path. Prepare for the encounter.'};bestiaryObserve();prepareInitiative();if(count>1||e[0]==='Alpha Wolf'){battle.group=roster.map(m=>({name:m[0],hp:m[2],max:m[2],attack:m[3],xp:m[4],threat:m[5],guard:false,heavy:false,type:'light'}));for(const m of battle.group)bestiaryEntry(m.name).seen=true;groupPick();groupSync()}else pickEnemyAttack();tab='combat';render()}
function beginEncounter(id){const q=s.guildContracts.find(x=>x.id===id);if(!q)return;if(q.expiresAt<=Date.now()){makeGuildContracts();save();render();return say('That contract has expired and the Guild has refreshed the board.')}battle={questId:id,returnTab:'quests',enemyName:q.enemy,enemyLevel:q.level,enemyMax:q.hp,enemyHp:q.hp,playerHp:s.character.hp??maxPlayerHp(),attackDamage:q.attack,xpReward:q.xpReward,threat:q.level>=3?'High':q.level===2?'Moderate':'Low',defendExercise:'crunches',counterExercise:'push-ups',turn:1,totalDamage:0,staggered:false,phase:'choose',mode:null,log:`A ${q.enemy} appears. Prepare for the encounter.`};prepareInitiative();pickEnemyAttack();tab='combat';render()}
function showDeath(){if(battle?.promotion)delete s.dungeonRoom;if(battle?.campaign)bestiaryEntry(battle.enemyName).losses++;if(timerHandle){clearInterval(timerHandle);timerHandle=null}battle=null;tab='guild';s.character.hp=1;s.recoveryPending=true;save();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));render();const d=document.createElement('dialog');d.id='victoryDialog';d.innerHTML='<div class="victory-heading"><div style="font-size:36px">☠</div><h2 style="color:#ef4444">You Have Been Defeated</h2><p>0 XP · 0 Gold · No loot</p><p>Remaining HP: 1 / '+maxPlayerHp()+'</p></div><button class="btn gold" style="width:100%">Return to Guild</button>';d.querySelector('button').onclick=()=>{d.close();showGuildRecovery()};d.addEventListener('close',()=>{d.remove();const chest=items.find(i=>i.chestKind);if(chest)openGearChest(chest.id)});d.addEventListener('cancel',e=>e.preventDefault());document.body.appendChild(d);d.showModal();}
function salePrice(i){return ({Common:1,Uncommon:2,Rare:5,Epic:10})[i.rarity]||0}function isMonsterPart(i){return i.id?.startsWith('loot:')&&salePrice(i)>0&&/^(Green Jelly|Blue Jelly|Acid Jelly|Slime Essence|Magic Stone|Mystic Water|Giant Slime Jelly|Giant Slime Essence|Giant Slime Core|Fenrir Fur|Fenrir Pelt|Fenrir's Fang|Fenrir Frost Core|Alpha Fur|Alpha Pelt|Alpha Fang|Alpha Core|Fur|Raw Meat|Wolf Pelt|Wolf Fang)$/.test(i.name)}function updateSaleTotal(index){const i=s.inventory[index],q=Number(document.getElementById('sale-qty-'+index)?.value),btn=document.getElementById('sale-btn-'+index);if(i&&btn&&Number.isInteger(q)&&q>=1&&q<=(i.quantity||1))btn.textContent='Sell · '+q*salePrice(i)+' Gold'}function gameConfirm({title,message,details='',total='',accept='Confirm',onConfirm}){if(document.getElementById('gameConfirmDialog'))return;const d=document.createElement('dialog');d.id='gameConfirmDialog';d.className='game-confirm';d.innerHTML='<h2>'+esc(title)+'</h2><p class="trade-dialogue">'+esc(message)+'</p>'+(details?'<div class="trade-details">'+esc(details)+'</div>':'')+(total?'<div class="trade-total"><span>Total sale value</span><strong>✦ '+esc(total)+'</strong></div>':'')+'<div class="trade-actions"><button class="btn ghost" data-cancel>Cancel</button><button class="btn gold" data-confirm>'+esc(accept)+'</button></div>';d.querySelector('[data-cancel]').onclick=()=>d.close();d.querySelector('[data-confirm]').onclick=()=>{if(!d.open)return;d.close();d.remove();onConfirm()};d.addEventListener('close',()=>d.remove());document.body.appendChild(d);d.showModal();d.querySelector('[data-cancel]').focus()}function sellMonsterPart(index){if(tab!=='merchant'||battle)return;const i=s.inventory[index];if(!i||!isMonsterPart(i))return;const count=i.quantity||1,q=Number(document.getElementById('sale-qty-'+index)?.value);if(!Number.isInteger(q)||q<1||q>count)return say('Invalid sale quantity.');const total=q*salePrice(i);gameConfirm({title:'Guild Merchant',message:'Ah, some fresh monster parts! Shall we make a trade?',details:i.name+' ×'+q+' · '+i.rarity,total:total+' Gold',accept:'Confirm Trade',onConfirm:()=>{const current=s.inventory.indexOf(i),available=i.quantity||1;if(tab!=='merchant'||battle||current<0||!isMonsterPart(i)||q>available||q*salePrice(i)!==total)return say('Trade no longer available.');if(q===available)s.inventory.splice(current,1);else i.quantity=available-q;s.character.gold+=total;localStorage.removeItem(UNDO_KEY);lastQuestUndo=null;save();render();say('A pleasure doing business with you, Adventurer. +'+total+' Gold.')}})}function healCharacter(){if(battle)return say('You cannot heal during an encounter.');if((s.character.hp??maxPlayerHp())>=maxPlayerHp())return;gameConfirm({title:"Guild Infirmary",message:'Restore your HP to full?',accept:"Restore Health",onConfirm:()=>{if(battle||(s.character.hp??maxPlayerHp())>=maxPlayerHp())return;s.character.hp=maxPlayerHp();s.recoveryPending=false;save();render();say('Health restored: '+maxPlayerHp()+' / '+maxPlayerHp()+' HP.')}})}
function showGuildRecovery(){const old=document.getElementById('recoveryDialog');if(old)return;const d=document.createElement('dialog');d.id='recoveryDialog';d.className='guild-recovery';const lectures=["You're lucky you made it back alive! Know your limits, Adventurer.","Five monsters and one Adventurer? Next time, consider the odds before charging in.","The Guild needs living Adventurers, not heroic gravestones. Be more careful!","Even a slime can defeat a careless Adventurer. Learn from this and return stronger."];d.innerHTML=`<div class="victory-heading"><h2>Guild Representative</h2><p>HP: 1 / ${maxPlayerHp()}</p></div>${guildPortrait()}<p>${lectures[Math.floor(Math.random()*lectures.length)]}</p><p>The Guild tends to your wounds.</p><button class="btn gold" style="width:100%">Understood — Recover HP</button>`;d.querySelector('button').onclick=()=>{s.character.hp=maxPlayerHp();s.recoveryPending=false;save();d.close();render();say('Health restored: '+maxPlayerHp()+' / '+maxPlayerHp()+' HP.')};d.addEventListener('close',()=>d.remove());d.addEventListener('cancel',e=>e.preventDefault());document.body.appendChild(d);d.showModal();}

function groupSync(){battle.killed=battle.group.filter(m=>m.hp===0).length;battle.enemyHp=battle.group.reduce((a,m)=>a+m.hp,0);battle.enemyMax=battle.group.reduce((a,m)=>a+m.max,0)}
function groupPick(){for(const m of battle.group){if(!m.hp)continue;if(!m.heavy||!m.move)m.move=rollMove(m.name||battle.enemyName);m.type=m.move[1]}}
function selectedEnemy(){return battle.group?.find(m=>m===battle.target&&m.hp)||null}
function selectEnemy(i){if(battle?.phase==='choose'&&battle.group&&(i===-1||battle.group[i]?.hp)){battle.target=i===-1?null:battle.group[i];render()}}
function attackKind(){if(battle?.gathering)return 'pickaxe';const w=equippedWeapon();return !w?'fist':w.attribute==='dexterity'?'bow':w.attribute==='intelligence'?'staff':'sword'}function attackMarker(m){const unit=m||battle,hit=unit.hitAt,impact=hit&&Date.now()-hit<1000,targeted=battle.phase==='challenge'&&battle.mode==='counter'&&(!m||!selectedEnemy()||selectedEnemy()===m)&&(!m||m.hp);if(!impact&&!targeted)return '';const kind=attackKind();if(kind==='pickaxe')return impact?'<span class="gather-anchor" data-hit="'+hit+'"></span>':'';if(!impact)return '<span aria-hidden="true" class="attack-marker '+kind+'"><span>'+({fist:'👊',sword:'🗡️',bow:'🏹',staff:'🪄'})[kind]+'</span></span>';if(kind==='bow'||kind==='staff')return '<span aria-hidden="true" class="ranged-anchor" data-kind="'+kind+'" data-hit="'+hit+'" data-slot="'+(m?battle.group.indexOf(m):0)+'" data-damage="'+(unit.hitDamage||0)+'" data-finish="'+Number((m?m.hp:battle.enemyHp)<=0)+'"></span>';const mirror=kind==='sword'&&unit.slashMirror;const art=kind==='sword'?'<path class="player-sweep" d="M5 115Q18 12 115 5Q55 35 5 115Z"/><path class="player-edge" d="M5 115Q30 20 115 5Q58 38 5 115Z"/>':'<path class="player-star" d="M60 4L72 38 105 16 85 48 118 60 84 72 104 104 72 85 60 118 48 85 16 104 36 72 2 60 36 48 16 16 48 38Z"/><circle class="player-ring" cx="60" cy="60" r="35"/><text class="player-punch" x="60" y="73" text-anchor="middle" font-size="38">👊</text>';return '<span aria-hidden="true" class="attack-marker player-impact '+kind+((m?m.hp:battle.enemyHp)<=0?' finishing':'')+(mirror?' mirrored':'')+'" style="--strike-angle:'+((hit%7-3)*12)+'deg"><svg viewBox="0 0 120 120">'+art+'</svg>'+(kind==='sword'?'<span class="sword-hit-splat"><svg viewBox="0 0 100 100"><path d="M50 3L63 22 84 13 80 36 98 50 79 64 86 87 63 80 50 98 36 80 13 87 21 64 2 50 21 36 14 13 36 22Z"/></svg><strong>'+(unit.hitDamage||0)+'</strong></span>':'<strong class="player-damage">−'+(unit.hitDamage||0)+'</strong>')+'</span>'}
function playRangedEffects(){const b=battle;if(!b)return;const seen=b.rangedSeen||(b.rangedSeen=new Set());const anchors=[...document.querySelectorAll('.ranged-anchor')];anchors.forEach((anchor,i)=>{const key=anchor.dataset.hit+':'+anchor.dataset.slot;if(seen.has(key))return;seen.add(key);const host=anchor.parentElement,sprite=host.querySelector('.wolf-sprite,.slime-sprite,svg,.unit-fallback'),r=(sprite||host).getBoundingClientRect(),tx=r.left+r.width*.5,ty=r.top+r.height*.58;const kind=anchor.dataset.kind,damage=anchor.dataset.damage,finish=anchor.dataset.finish==='1';const sx=12,sy=window.innerHeight-12,dx=tx-sx,dy=ty-sy,len=Math.hypot(dx,dy),angle=Math.atan2(dy,dx)*180/Math.PI;setTimeout(()=>{if(battle!==b||tab!=='combat')return;const layer=document.createElement('div');layer.className='ranged-fx '+kind+(finish?' finishing':'');layer.setAttribute('aria-hidden','true');layer.style.cssText='--sx:'+sx+'px;--sy:'+sy+'px;--tx:'+tx+'px;--ty:'+ty+'px;--len:'+len+'px;--angle:'+angle+'deg';layer.innerHTML='<div class="ranged-track"><i class="ranged-trail"></i><i class="ranged-projectile"></i></div><div class="ranged-impact"><i></i>'+(kind==='bow'?'<span class="bow-hit-splat"><svg viewBox="0 0 100 100"><path d="M50 3L63 22 84 13 80 36 98 50 79 64 86 87 63 80 50 98 36 80 13 87 21 64 2 50 21 36 14 13 36 22Z"/></svg><strong>'+damage+'</strong></span>':'<b>−'+damage+'</b>')+'</div>';document.body.appendChild(layer);const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(!reduced)setTimeout(()=>{if(sprite?.isConnected)sprite.animate([{translate:'0',filter:'brightness(1)'},{translate:'5px -3px',filter:'brightness(1.6)'},{translate:'0',filter:'brightness(1)'}],{duration:250})},280);setTimeout(()=>layer.remove(),1000)},i*120)})}
function groupDamage(group,reps,dodge){const target=selectedEnemy();let total=0;for(const m of target?[target]:group){if(!m.hp||reps<=0)continue;const cost=m.guard?2:1;if(dodge(m)){m.guard=false;break}const hit=Math.min(phaseCap(m.hp,m.max,m),Math.floor(reps/cost));m.hp-=hit;if(hit>0){m.hitAt=Date.now();m.hitDamage=hit;if(attackKind()==='sword'){if(total===0)battle.slashMirror=!battle.slashMirror;m.slashMirror=battle.slashMirror}}m.guard=false;total+=hit;reps-=hit*cost;if(m.hp)break}if(target&&!target.hp)battle.target=null;return total}
function bossIcon(m){const n=phaseCount(m);return n===1?'':'<span class="boss-icon '+(n===3?'elite':'mini')+'" aria-label="'+(n===3?'Boss':'Mini-boss')+'">☠</span> '}function howlWarning(){return battle.howlAt&&Date.now()-battle.howlAt<4000?'<div role="alert" class="howl-warning" style="animation-delay:-'+(Date.now()-battle.howlAt)+'ms">❗ The boss is calling for help!</div>':''}function unitThreshold(m){const n=phaseCount(m);if(n===1)return '';return '<div style="display:flex;gap:2px;width:90%;margin:2px auto" aria-label="'+n+' HP thresholds">'+Array.from({length:n},(_,i)=>{const lo=Math.floor(i*m.max/n),hi=Math.floor((i+1)*m.max/n),p=Math.max(0,Math.min(100,100*(m.hp-lo)/(hi-lo)));return '<div style="flex:1;height:6px;background:#392c29;border:1px solid #bca06a"><div style="height:100%;width:'+p+'%;background:'+(n===3?'#a16bd2':'#609bd4')+'"></div></div>'}).join('')+'</div>'}
function groupStrike(block=0){let damage=0,blocked=0,notes=[];for(const m of [...battle.group]){if(!m.hp||!battle.playerHp)continue;bestiaryObserve(moveLabel(m.move,m.type),m.name);notes.push(moveLabel(m.move,m.type));if(m.type==='summon'){slimeAttackVisual(m.name,m.move,'hit',m);battle.howlAt=Date.now();if(!battle.howlUsed&&battle.group.length<5){battle.howlUsed=true;const w={name:'Wild Wolf',hp:8,max:8,attack:3,xp:12,threat:'Common',guard:false,heavy:false,move:['Bite','light',60],type:'light'};battle.group.splice(battle.group.indexOf(m),0,w);battle.count=battle.group.length;groupSync();bestiaryEntry(w.name).seen=true;notes.push('A Wild Wolf answers the howl!')}else notes.push('No reinforcements answer');continue}if(m.type==='guard'){m.guard=true;notes.push('Guard');continue}if(m.type==='heavy'&&!m.heavy){m.heavy=true;notes.push('Heavy charging');continue}if(m.move?.[0]==='Triple Spit'){const t=tripleSpit(m,block);block-=t.blocked;blocked+=t.blocked;damage+=t.damage;notes.push(t.dodges+' projectiles dodged');continue}const bonus=packBonus(m,battle.group);const hit=rollEnemyDamage(m.attack??battle.attackDamage,m.type==='heavy')+bonus;if(bonus)notes.push(m.name+' Pack +'+bonus);m.heavy=false;if(playerDodge()){slimeAttackVisual(m.name,m.move,'dodge',m);notes.push('Dodged');continue}const b=Math.min(block,hit);block-=b;blocked+=b;const taken=hit-b;slimeAttackVisual(m.name,m.move,taken?"hit":"block",m);damage+=taken;battle.playerHp=Math.max(0,battle.playerHp-taken);if(m.type==='rush'&&taken&&battle.playerHp&&moveStuns(m.move))battle.stunned=true}return 'Group attacks: '+damage+' damage, '+blocked+' blocked.'+(notes.length?' '+notes.join(', ')+'.':'')+(battle.stunned?' Stunned!':'')}
function startGroup(mode){if(battle.stunned){battle.stunned=false;battle.log='You lose this turn recovering from stun. '+groupStrike();battle.groupActed=false;if(!battle.playerHp)return showDeath();battle.openingTurn=false;battle.turn++;groupPick();rollInitiative();render();return}battle.target=selectedEnemy();battle.mode=mode;battle.phase='challenge';timeLeft=challengeLimit();battle.log=mode==='block'?'Defend against the group.': 'Attack '+(battle.target?.name||'all enemies')+'.';if(mode==='counter'&&!battle.playerFirst){battle.log=groupStrike();if(!battle.playerHp)return showDeath();if(battle.stunned){battle.stunned=false;battle.log+=' Your attack is cancelled by stun.';battle.phase='choose';battle.mode=null;battle.groupActed=false;battle.turn++;battle.openingTurn=false;groupPick();rollInitiative();render();return}battle.log+=' Attack '+(battle.target?.name||'all enemies')+'.';battle.groupActed=true}render()}
function clearAttackVisuals(b){setTimeout(()=>{if(battle===b&&tab==='combat'&&battle.phase==='choose'){render()}},1050)}function resolveGroup(raw){if(battle.mode==='block'){battle.log=groupStrike(raw)}else{const damage=groupDamage(battle.group,attackDamageForReps(raw),m=>rollDodge(enemyDex(m.name)));battle.totalDamage+=damage;clearAttackVisuals(battle);groupSync();battle.log='You deal '+damage+' damage. '+battle.killed+'/'+battle.count+' defeated.';if(!battle.enemyHp){battle.phase='victory';render();setTimeout(()=>{if(battle&&battle.phase==='victory')finishEncounter(true)},1600);return}if(!battle.groupActed)battle.log+=' '+groupStrike()}if(!battle.playerHp)return showDeath();battle.groupActed=false;battle.openingTurn=false;battle.turn++;battle.phase='choose';battle.mode=null;groupPick();rollInitiative();render()}
function startChallenge(mode){if(!battle||battle.phase!=='choose')return;if(battle.gathering){battle.mode='counter';battle.phase='challenge';timeLeft=challengeLimit();render();return}if(battle.group)return startGroup(mode);if(battle.stunned){battle.stunned=false;battle.log='You recover from the stun and lose this turn. '+enemyStrike();if(battle.playerHp===0){showDeath();return}else{battle.turn++;pickEnemyAttack();rollInitiative()}render();return}battle.mode=mode;battle.phase='challenge';battle.actionIcon=mode==='block'?'🛡':'⚔';battle.actionTarget=mode==='block'?'player':'enemy';battle.actionLabel=mode==='block'?'Shield block':'Player attack';timeLeft=challengeLimit();if(mode==='counter'){battle.skipEnemyAction=!!battle.staggered;battle.staggered=false;if(battle.skipEnemyAction){battle.log='Enemy staggered: your attack is safe this turn.'}else if(battle.playerFirst){battle.log='You have initiative! Strike before the enemy acts.'}else{battle.log=enemyStrike();if(battle.playerHp===0){showDeath();return}if(battle.stunned){battle.stunned=false;battle.log+=' Your attack is cancelled by stun.';battle.phase='choose';battle.mode=null;battle.turn++;battle.openingTurn=false;pickEnemyAttack();rollInitiative();render();return}battle.log+=' Prepare your attack.'}}else{battle.log='You brace against '+battle.enemyName+'. '+attackPreview()+'. Complete defensive reps to block damage and stagger the enemy.'}render()}
function phaseCount(m=battle){const name=m.name||m.enemyName;return ['Fenrir','Alpha Wolf','Goblin King'].includes(name)||['Epic','Zone boss'].includes(m.threat)?3:['Slime King','Goblin Shaman'].includes(name)||m.threat==='Rare'||m.threat==='Mini-boss'?2:1}
function phaseCap(hp,max,m=battle){const n=phaseCount(m);if(n===1)return hp;const bounds=Array.from({length:n},(_,i)=>Math.floor(i*max/n));return hp-Math.max(...bounds.filter(x=>x<hp),0)}
function thresholdBar(){const n=phaseCount();if(n===1||battle.group)return '';return '<div style="display:flex;gap:4px;margin:6px 0">'+Array.from({length:n},(_,i)=>{const lo=Math.floor(i*battle.enemyMax/n),hi=Math.floor((i+1)*battle.enemyMax/n),pct=Math.max(0,Math.min(100,(battle.enemyHp-lo)/(hi-lo)*100));return '<div style="flex:1;background:#392c29;height:10px;border:1px solid #bca06a"><div style="height:100%;background:'+(n===3?'#a16bd2':'#609bd4')+';width:'+pct+'%"></div></div>'}).join('')+'</div><div class="small">'+n+' HP THRESHOLDS</div>'}
function challengeLimit(){if(battle?.gathering)return Math.max(1,phaseCap(battle.enemyHp,battle.enemyMax));return Math.max(1,Math.ceil(battle?.enemyHp||1))}
function timerText(n){return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
function startTimer(){if(!battle||battle.phase!=='challenge'||timerHandle)return;const btn=document.querySelector('#timerStart');if(btn)btn.disabled=true;timeLeft=challengeLimit();if(DEV_MODE){timeLeft=0;document.querySelector('#timer').textContent=timerText(0);document.querySelector('#repEntry').style.display='block';if(btn)btn.style.display='none';return}const tick=()=>{timeLeft--;const el=document.querySelector('#timer');if(el)el.textContent=timerText(Math.max(0,timeLeft));if(timeLeft<=0){clearInterval(timerHandle);timerHandle=null;const entry=document.querySelector('#repEntry');if(entry)entry.style.display='block';const start=document.querySelector('#timerStart');if(start)start.style.display='none';}};timerHandle=setInterval(tick,1000)}
function resolveChallenge(){if(!battle||battle.phase!=='challenge')return;const raw=Number(document.querySelector('#repCount')?.value);if(!Number.isInteger(raw)||raw<0||raw>challengeLimit())return say('Enter a whole number from 0 to '+challengeLimit()+'.');if(timerHandle){clearInterval(timerHandle);timerHandle=null}if(battle.gathering){const b=battle,damage=Math.min(raw,phaseCap(b.enemyHp,b.enemyMax));b.enemyHp-=damage;b.hitAt=damage?Date.now():0;b.hitDamage=damage;b.phase=b.enemyHp?'choose':'victory';b.mode=null;b.log=b.enemyHp?'Node HP: '+b.enemyHp+'/20':'Node broken!';render();if(!b.enemyHp)setTimeout(()=>{if(battle===b)finishGather()},1100);return}if(battle.group)return resolveGroup(raw);if(battle.mode==='block'){battle.actionIcon='🛡';battle.actionTarget='player';battle.actionLabel='Defense';const type=battle.attackType,guard=type==='guard',windup=type==='heavy'&&!battle.heavyCharged;bestiaryObserve(moveLabel(battle.move,type));if(guard){battle.guarding=true;battle.log='You defend while the enemy takes a defensive stance. Its next incoming hit is reduced.'}else if(windup){if(raw>=battle.attackDamage){battle.heavyCharged=false;battle.staggered=true;battle.log='Heavy attack interrupted! Enemy staggered. Your next attack is safe.'}else{battle.heavyCharged=true;battle.log='Interrupt failed: '+raw+'/'+battle.attackDamage+' defensive reps. HEAVY ATTACK INCOMING next turn!'}}else if(battle.move?.[0]==='Triple Spit'){const t=tripleSpit(null,raw);battle.log='Triple Spit: '+t.damage+' damage, '+t.blocked+' blocked, '+t.dodges+' dodged.';battle.staggered=true}else{const damage=rollEnemyDamage(battle.attackDamage,type==='heavy'),blocked=Math.min(damage,raw),taken=damage-blocked,dodged=playerDodge();slimeAttackVisual(battle.enemyName,battle.move,dodged?"dodge":taken?"hit":"block");battle.playerHp=Math.max(0,battle.playerHp-(dodged?0:taken));if(type==='heavy')battle.heavyCharged=false;if(type==='rush'&&!dodged&&taken>0&&battle.playerHp>0&&moveStuns(battle.move))battle.stunned=true;battle.log=dodged?'You dodge the '+type+' attack!':'You block '+blocked+' damage from '+moveLabel(battle.move,type)+' and take '+taken+'.';if(battle.stunned)battle.log+=' You are STUNNED for your next turn!';battle.staggered=true}}else{battle.actionIcon='⚔';battle.actionTarget='player';battle.actionLabel='Player attack';const dodged=rollDodge(battle.enemyDex),damage=dodged?0:Math.min(phaseCap(battle.enemyHp,battle.enemyMax),battle.guarding?Math.floor(attackDamageForReps(raw)/2):attackDamageForReps(raw));battle.enemyHp=Math.max(0,battle.enemyHp-damage);if(damage>0){battle.hitAt=Date.now();battle.hitDamage=damage;if(attackKind()==='sword')battle.slashMirror=!battle.slashMirror;clearAttackVisuals(battle)}battle.totalDamage+=damage;battle.log=dodged?battle.enemyName+' dodges your attack!':'You deal '+damage+' damage'+(battle.guarding?' (enemy guard reduced damage)':'')+'.';battle.guarding=false;if(battle.playerFirst&&!battle.skipEnemyAction&&battle.enemyHp>0)battle.log+=' '+enemyStrike()}if(battle.enemyHp===0){if(battle.campaign&&battle.killed+1<battle.count){battle.killed++;battle.enemyHp=battle.enemyMax;battle.staggered=false;battle.guarding=false;battle.heavyCharged=false;battle.stunned=false;battle.phase='choose';battle.mode=null;battle.turn=1;battle.log='Enemy defeated! Next monster approaches ('+(battle.killed+1)+'/'+battle.count+').';prepareInitiative();pickEnemyAttack();render();return}battle.phase='victory';battle.log+=' Enemy defeated!';render();setTimeout(()=>{if(battle&&battle.phase==='victory')finishEncounter(true)},1600);return}if(battle.playerHp===0){showDeath();return}battle.turn++;battle.openingTurn=false;battle.phase='choose';battle.mode=null;pickEnemyAttack();rollInitiative();render()}
function showVictory(enemy,xp,gold,loot,attributeXp=0,attributeKey='strength',rankAward=0,conXp=0,levelChests=[],gathering=false,onContinue=null){const items=Array.isArray(loot)?loot:loot?[loot]:[];const old=document.getElementById('victoryDialog');if(old)old.remove();const d=document.createElement('dialog');d.id='victoryDialog';d.setAttribute('aria-labelledby','victoryTitle');d.innerHTML=`<div class="victory-heading"><div style="font-size:36px">🏆</div><h2 id="victoryTitle">${gathering?"Node Broken!":"Battle Won!"}</h2><p>${esc(enemy)} ${gathering?"gathered":"defeated"}</p></div><div class="victory-rewards">${gathering?"":`<div class="between"><span>Experience obtained</span><b>+${formatXp(xp)} XP</b></div><div class="between"><span>Gold obtained</span><b style="color:#e7bf65">+${gold} Gold</b></div>`}${attributeXp?`<div class="between"><span>${attributeName(attributeKey)} XP</span><b>+${formatXp(attributeXp)}</b></div>`:''}${conXp?`<div class="between"><span>Constitution XP</span><b>+${formatXp(conXp)}</b></div>`:''}${rankAward?'<div class="between"><span>Rank XP</span><b>+10</b></div>':''}${items.map(loot=>`<div class="between"><span>Item obtained</span><b style="color:${rarityColor(loot.rarity)}">${esc(loot.name)} ×1</b></div>`).join('')}</div><button class="btn gold" style="width:100%;margin-top:16px" autofocus>Continue</button>`;d.querySelector('button').onclick=()=>d.close();d.addEventListener('close',()=>{d.remove();showLevelRewards(levelChests);if(onContinue)onContinue()});d.addEventListener('cancel',e=>e.preventDefault());document.body.appendChild(d);d.showModal();}
function finishEncounter(victory){if(timerHandle){clearInterval(timerHandle);timerHandle=null}if(battle.promotion)return finishPromotion(victory);if(battle.campaign){if(victory){markQuestUndo();const e=battle.enemyName,count=battle.count||1,roster=battle.group||[{name:e,xp:battle.xpReward,threat:battle.threat}],xp=roster.reduce((a,m)=>a+m.xp,0),loots=[];const rewards=new Map();for(const m of roster){const drops=monsterLoot(m.name,m.threat);loots.push(...drops,...patternDrops(m.name));const v=rewards.get(m.name)||{count:0,loot:[]};v.count++;v.loot.push(...drops);rewards.set(m.name,v)}for(const [name,v] of rewards)bestiaryWin(name,v.count,v.loot);if(Math.random()<.10)loots.push(grantGearChest());const attributeXp=xp/2,attributeKey=combatAttribute();s.character[attributeKey+'Xp']=(s.character[attributeKey+'Xp']||0)+attributeXp;s.character.hp=battle.playerHp;const conXp=attributeXp/5;s.character.constitutionXp=(s.character.constitutionXp||0)+conXp;const levelChests=awardCharacterXp(xp);const [regionName,key]=campaignRegions()[battle.campaignRegion||0];if(!battle.farming)s.world[key]=Math.max(s.world[key],battle.campaignIndex+1);s.completed.push({id:'CAM-'+Date.now(),title:e+' · '+regionName+(battle.farming?' Farming':' Campaign'),type:battle.farming?'FARMING VICTORY':'CAMPAIGN VICTORY',campaignVersion:2,campaignRegion:battle.campaignRegion||0,campaignIndex:battle.campaignIndex,description:battle.farming?'Repeat encounter cleared.':'Defeated in the regional campaign.',xpReward:xp,xpAwarded:xp,attributeXp,attributeKey,enemyLevel:battle.enemyLevel,loots,count,conXp,date:new Date().toLocaleDateString(),result:'VICTORY'});const rankAward=!battle.farming?10:0;save();battle=null;tab='world';render();showVictory(e+(count>1?' ×'+count:''),xp,0,loots,attributeXp,attributeKey,rankAward,conXp,levelChests)}else{battle=null;tab='world';render()}return}const i=s.guildContracts.findIndex(q=>q.id===battle.questId);if(i<0){tab='quests';battle=null;render();return}const q=s.guildContracts[i];if(victory){markQuestUndo();s.character.hp=battle.playerHp;const attributeKey=combatAttribute();s.character[attributeKey+'Xp']=(s.character[attributeKey+'Xp']||0)+battle.xpReward/2;const conXp=battle.xpReward/10;s.character.constitutionXp=(s.character.constitutionXp||0)+conXp;q.progress=(q.progress||0)+1;s.guildHistory.push({title:q.title,enemy:q.enemy,completedAt:Date.now(),recycleAt:Date.now()+DAY,result:'ENCOUNTER VICTORY'});if(q.progress>=q.target){s.guildContracts.splice(i,1);const xp=awardQuest(q);s.completed.push({...q,xpAwarded:xp,date:new Date().toLocaleDateString(),result:'CONTRACT COMPLETE'});s.guildHistory.push({title:q.title,completedAt:Date.now(),recycleAt:Date.now()+DAY,result:'CONTRACT COMPLETE'});makeGuildContracts();save();battle=null;tab='record';render();say(`CONTRACT COMPLETE! +${q.reward} Gold · +${formatXp(xp)} XP · +${formatXp(conXp)} Constitution XP.`)}else{save();const progress=q.progress;const title=q.title;battle=null;tab='quests';render();say(`${q.enemy} defeated! Contract progress: ${progress}/${q.target}.  +${formatXp(conXp)} Constitution XP. Gold and character XP awarded on contract completion.`)}}else{battle=null;tab='quests';render()}}
function escapeEncounter(){if(!battle)return;if(battle.promotion)return say('You cannot retreat from this dungeon.');const destination=battle.returnTab|| (battle.campaign?'world':'quests');if(timerHandle){clearInterval(timerHandle);timerHandle=null}s.character.hp=battle.playerHp;save();battle=null;tab=destination;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));render();say('You escaped safely. No rewards from this battle were earned. Previous progress is preserved.')}
function buy(id,name,cost){if(s.character.gold<cost)return;gameConfirm({title:"Guild Merchant",message:`Purchase ${name} for ${cost} Gold?`,accept:"Confirm Purchase",onConfirm:()=>{if(s.character.gold<cost)return;s.character.gold-=cost;s.purchases.push({id,name,cost});s.inventory.push({id,name});save();render();say('Purchase recorded.')}})}
function backup(){let a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify(s,null,2)],{type:'application/json'}));a.href=u;a.download='ACodex-backup.json';a.click();URL.revokeObjectURL(u);say('Backup export started.')}
function restore(e){let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{let x=JSON.parse(r.result);if(!x.character||!Array.isArray(x.active)||!Array.isArray(x.completed))throw 0;gameConfirm({title:'Guild Archives',message:'Replace current progress with this backup? Your current saved progress will be overwritten.',accept:'Restore Backup',onConfirm:()=>{try{s=x;save();render();say('Backup restored.')}catch(_){say('Could not restore backup.')}}})}catch(_){say('Invalid backup file.')}e.target.value=''};r.readAsText(f)}
let codexOpeningTimer=null,codexOpeningFinished=false;
function summonCodex(){const title=document.getElementById('codexTitle');if(title.classList.contains('summoning')||title.classList.contains('opening'))return;title.classList.add('summoning');title.querySelector('.shelf-codex').disabled=true;setTimeout(enterCodex,matchMedia('(prefers-reduced-motion: reduce)').matches?0:1500)}
function enterCodex(){const title=document.getElementById('codexTitle');if(title.classList.contains('opening'))return;title.classList.add('opening');title.classList.remove('summoning');title.querySelector('.title-enter').disabled=true;setTimeout(()=>{if(!codexOpeningFinished)title.querySelector('.title-inscription').focus()},matchMedia('(prefers-reduced-motion: reduce)').matches?0:1500);codexOpeningTimer=setTimeout(finishCodexOpening,6600);}
function finishCodexOpening(){const title=document.getElementById('codexTitle');if(!title.classList.contains('opening')||codexOpeningFinished)return;codexOpeningFinished=true;clearTimeout(codexOpeningTimer);tab=s.dungeonRoom!=null?'dungeon':'status';characterSection='status';render();const reveal=()=>{title.hidden=true;document.querySelector('.app').inert=false;document.querySelector('main')?.setAttribute('tabindex','-1');document.querySelector('main')?.focus();};if(matchMedia('(prefers-reduced-motion: reduce)').matches){reveal();return;}const flash=document.createElement('div');flash.id='codexFlash';flash.setAttribute('aria-hidden','true');document.body.appendChild(flash);flash.classList.add('visible');setTimeout(()=>flash.classList.add('lit'),20);setTimeout(()=>{reveal();flash.classList.remove('lit');},400);setTimeout(()=>flash.remove(),950);}

document.querySelector('.app').inert=true;
save();render();setInterval(trainingClock,1000);

let availableBuild=null,updateChecking=false;
const updateSteps=['Check version','Confirm live deployment','Retrieve and verify game files','Preserve character save','Load updated game'];
function newerBuild(a,b){const x=a.split('.').map(Number),y=b.split('.').map(Number);for(let i=0;i<Math.max(x.length,y.length);i++){const d=(x[i]||0)-(y[i]||0);if(d)return d>0}return false}
async function updateFetch(path){const url=new URL(path,location.href);url.searchParams.set('check',Date.now());const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),12000);try{const r=await fetch(url,{cache:'no-store',signal:controller.signal});if(!r.ok)throw Error('HTTP '+r.status);return await r.text()}finally{clearTimeout(timeout)}}
async function liveVersion(){const data=JSON.parse(await updateFetch('./version.json'));if(typeof data.build!=='string'||!/^\d+(\.\d+)+$/.test(data.build))throw Error('Invalid version metadata');return data.build}
function updateWindow(){const d=document.createElement('dialog');d.className='game-confirm';d.id='guildUpdateDialog';d.innerHTML='<h2>✦ Guild Update ✦</h2><p class="trade-dialogue">New dispatches from the Guild.</p><p id="guildUpdateMessage" role="status"></p><progress id="guildUpdateProgress" max="5" value="0" style="width:100%;height:18px;accent-color:#c6a158"></progress><div id="guildUpdateSteps"></div><button class="btn ghost" id="guildUpdateClose" disabled>Close</button>';d.addEventListener('cancel',e=>{if(updateChecking)e.preventDefault()});d.addEventListener('close',()=>d.remove());d.querySelector('button').onclick=()=>d.close();document.body.appendChild(d);d.showModal();return d}
function updateStage(d,n,message){if(!d)return;d.querySelector('progress').value=n;d.querySelector('#guildUpdateMessage').textContent=message;d.querySelector('#guildUpdateSteps').innerHTML=updateSteps.map((label,i)=>'<p style="font-size:13px;color:'+(i<n?'#9ed39c':'#c9baa0')+'">'+(i<n?'✓ ':i===n?'◉ ':'○ ')+label+'</p>').join('')}
async function checkGameUpdate(manual=false){if(updateChecking)return;const status=document.getElementById('updateStatus'),button=document.getElementById('updateGame');if(manual&&(battle||document.querySelector('dialog[open]'))){status.textContent='Finish your encounter or dialogue before updating.';return}updateChecking=true;let d=null;try{if(manual&&availableBuild){d=updateWindow();updateStage(d,0,'Checking latest version…')}else if(manual)status.textContent='Checking Guild dispatches…';const remote=await liveVersion(),current=document.getElementById('build-id').textContent.trim().replace('BUILD ','');if(!newerBuild(remote,current)){availableBuild=null;button.textContent='Check for Update';if(manual)status.textContent='You are on the latest build. Guild dispatch received.';updateStage(d,0,'No newer build is available.');return}availableBuild=remote;button.textContent='Update Game';status.textContent='New build available: '+remote;if(!d)return;updateStage(d,1,'Confirming deployment…');let html='',found=false;for(let attempt=0;attempt<6;attempt++){html=await updateFetch('./index.html');const build=html.match(/id="build-id">BUILD ([0-9.]+)<\/span>/)?.[1];if(build===remote){found=true;break}updateStage(d,1,'Awaiting deployment… retry '+(attempt+1)+' of 6');if(attempt<5)await new Promise(resolve=>setTimeout(resolve,3000))}if(!found)throw Error('Deployment is not ready yet. Close and retry shortly.');updateStage(d,2,'Live deployment confirmed. Verifying game files…');if(!html.includes('</html>'))throw Error('Incomplete game file');if(html.includes('src="./game.js"')){for(const path of ['./game.js','./style.css','./assets/monsters/wolf-sprites.js','./assets/portraits/preset-portraits.js']){const file=await updateFetch(path);if(!file.trim()||/^\s*<!doctype html/i.test(file))throw Error('Incomplete game asset: '+path);if(path==='./game.js'&&!file.includes('function checkGameUpdate'))throw Error('Incomplete game script')}}else if(!html.includes('function checkGameUpdate'))throw Error('Incomplete game file');updateStage(d,3,'Game files verified. Preserving character save…');save();sessionStorage.setItem('acodex_update_target',remote);updateStage(d,4,'Save preserved. Loading updated game…');const url=new URL('./',location.href);url.searchParams.set('v',remote);location.replace(url.href)}catch(e){const message=navigator.onLine?'Update check failed: '+e.message:'Offline. Connect to check for updates.';if(manual)status.textContent=message;if(d)d.querySelector('#guildUpdateMessage').textContent=message}finally{updateChecking=false;if(d){d.querySelector('button').disabled=false;d.querySelector('button').textContent='Close / Retry'}}}
try{const target=sessionStorage.getItem('acodex_update_target');if(target){sessionStorage.removeItem('acodex_update_target');const current=document.getElementById('build-id').textContent.trim().replace('BUILD ','');if(current===target){const d=updateWindow();updateStage(d,5,'Update complete! Build '+current);d.querySelector('button').disabled=false;d.querySelector('button').textContent='Return to Game';document.getElementById('updateStatus').textContent='Update complete: '+current}else document.getElementById('updateStatus').textContent='New build not loaded yet. Please retry.'}}catch(e){}
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
window.addEventListener('online',()=>checkGameUpdate());document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkGameUpdate()});setInterval(()=>checkGameUpdate(),120000);checkGameUpdate();


let installEvent=null;const installStatus=document.getElementById('installStatus');window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;installStatus.textContent='App ready to install';const b=document.createElement('button');b.className='btn gold';b.textContent='Install ACodex';b.onclick=async()=>{if(!installEvent)return;await installEvent.prompt();installEvent=null;b.remove()};installStatus.appendChild(b)});window.addEventListener('appinstalled',()=>{installStatus.textContent='ACodex installed'});if(matchMedia('(display-mode: standalone)').matches)installStatus.textContent='ACodex installed';else if('serviceWorker' in navigator)navigator.serviceWorker.ready.then(()=>{if(!installEvent)installStatus.textContent='Offline service ready · use Chrome menu to install'});else installStatus.textContent='Offline service unavailable';

function gatherRock(){const b=battle,wood=b.enemyName==='Wood Log',cls=b.enemyHp===0?' shattered':b.enemyHp<=10?' cracked':'';return '<svg class="gather-rock'+cls+'" viewBox="0 0 160 110"><g class="rock-left"><path d="M15 90L8 65 30 25 72 12 80 55 65 95Z" fill="'+(wood?'#805431':'#777e86')+'" stroke="#333" stroke-width="3"/></g><g class="rock-right"><path d="M72 12L119 24 150 65 139 94 65 95 80 55Z" fill="'+(wood?'#a77b49':'#a3aab0')+'" stroke="#333" stroke-width="3"/></g><path class="rock-crack" d="M72 12L80 55 65 95M80 55L110 46" fill="none" stroke="#25272a" stroke-width="5"/></svg>'}

function playGatherSwing(){const b=battle,a=document.querySelector('.gather-anchor');if(!b?.gathering||!a||b.gatherSeen===a.dataset.hit)return;b.gatherSeen=a.dataset.hit;const rock=document.querySelector('.gather-rock');if(!rock||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const r=rock.getBoundingClientRect(),x=r.left+r.width*.55,y=r.top+r.height*.5,H=window.innerHeight,W=window.innerWidth;const layer=document.createElement('div');layer.className='gather-swing-layer';layer.innerHTML='<svg viewBox="0 0 '+W+' '+H+'"><path class="gather-trail" pathLength="1" d="M12 '+(H-18)+' Q'+(x*.18)+' '+(y+100)+' '+x+' '+y+'"/><g transform="translate('+x+' '+y+')"><g class="gather-impact"><path d="M-25 -15L-7 -34 8 -12 30 0 8 9 14 30 -9 12 -30 4Z"/>'+Array.from({length:8},(_,i)=>'<path transform="rotate('+(i*45)+')" d="M0 -35L0 -52"/>').join('')+'</g></g></svg>';document.body.appendChild(layer);if(b.enemyHp>0)rock.animate([{transform:'translateX(0)'},{transform:'translateX(-5px)'},{transform:'translateX(5px)'},{transform:'translateX(0)'}],{duration:260,delay:260});setTimeout(()=>layer.remove(),1000)}

function enterSlimeDen(){if(battle||!promotionReady()||s.dungeonRoom!=null)return;s.dungeonRoom=0;save();const veil=document.createElement('div');veil.className='dungeon-entrance';veil.innerHTML='<div class="wax-seal">F</div><h2>Good luck, Adventurer!</h2><small>F-RANK PROMOTION TRIAL</small>';document.body.appendChild(veil);const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;setTimeout(()=>{veil.classList.add('black');startPromotionRoom(0);setTimeout(()=>veil.remove(),reduced?0:650)},reduced?0:2200)}
