function showRankApproval(previous,next,dungeon,unlocked){const d=document.createElement('dialog');d.id='rankApprovalDialog';d.className='rank-approval';d.innerHTML='<h2>DUNGEON CLEARED!</h2><p>'+esc(dungeon)+'</p><div class="rank-stamp"><div class="wax-seal">'+esc(next)+'</div></div><div class="rank-approved"><h2>RANK PROMOTION APPROVED!</h2><h3>'+esc(previous)+' → '+esc(next)+'</h3><p>Congratulations, Adventurer!</p><p>'+esc(unlocked)+' unlocked</p><button class="btn gold" disabled>Continue</button></div>';const btn=d.querySelector('button');btn.onclick=()=>d.close();d.addEventListener('cancel',e=>e.preventDefault());d.addEventListener('close',()=>d.remove());document.body.appendChild(d);d.showModal();const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;setTimeout(()=>{if(!d.open)return;d.classList.add('stamped');levelConfetti(d);btn.disabled=false;btn.focus()},reduced?0:1100)}

function devResetRank(){if(!DEV_MODE||battle||s.dungeonRoom!=null)return;gameConfirm({title:'Developer Rank Reset',message:'Reset rank to F? All area progress, items, stats and Gold remain unchanged.',accept:'Reset Rank',onConfirm:()=>{if(!DEV_MODE||battle||s.dungeonRoom!=null)return;s.character.rank='F';clearTradeUndo();save();render();say('Test rank reset to F.')}})}
